CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE user_identities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_neutral_subject_id UUID UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT, display_name TEXT NOT NULL, legal_name TEXT, status TEXT NOT NULL CHECK (status IN ('PENDING_VERIFICATION','ACTIVE','SUSPENDED','LOCKED','DISABLED','DELETED')), primary_authentication_method TEXT NOT NULL, identity_assurance_level TEXT NOT NULL, email_verified_at TIMESTAMPTZ, phone_verified_at TIMESTAMPTZ, last_authenticated_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE authentication_methods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES user_identities(id), method_type TEXT NOT NULL, provider TEXT NOT NULL, provider_subject_reference TEXT NOT NULL, status TEXT NOT NULL, verified_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, provider, provider_subject_reference));
CREATE TABLE user_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES user_identities(id), workspace_id UUID, session_token_hash TEXT UNIQUE NOT NULL, authentication_method_id UUID NOT NULL REFERENCES authentication_methods(id), identity_assurance_level TEXT NOT NULL, device_id UUID, ip_context TEXT, user_agent_context TEXT, issued_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, revoked_by UUID, revocation_reason TEXT, status TEXT NOT NULL CHECK (status IN ('ACTIVE','REVOKED','EXPIRED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX user_sessions_active_idx ON user_sessions(user_id, expires_at) WHERE status = 'ACTIVE';
CREATE TABLE trusted_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES user_identities(id), device_fingerprint_hash TEXT NOT NULL, display_name TEXT NOT NULL, device_type TEXT NOT NULL, trust_status TEXT NOT NULL, first_seen_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, trusted_at TIMESTAMPTZ, trust_expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, device_fingerprint_hash));
CREATE TABLE step_up_challenges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES user_identities(id), session_id UUID NOT NULL REFERENCES user_sessions(id), required_assurance_level TEXT NOT NULL, reason TEXT NOT NULL, challenge_type TEXT NOT NULL, status TEXT NOT NULL, issued_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
